"""Helpers to construct journal records (development/testing only)."""
import struct, zlib

BEGIN, PATCH, COMMIT, ABORT = 1, 2, 3, 4

def rec(seq, kind, txid, payload=b'', length=None, crc=None):
    if length is None:
        length = len(payload)
    header = struct.pack('<IIBI', length, seq, kind, txid)
    body = header + payload
    if crc is None:
        crc = zlib.crc32(body) & 0xffffffff
    return body + struct.pack('<I', crc)

def begin(seq, txid, **kw):
    return rec(seq, BEGIN, txid, b'', **kw)

def patch(seq, txid, page, off, data, **kw):
    payload = struct.pack('<HHH', page, off, len(data)) + data
    return rec(seq, PATCH, txid, payload, **kw)

def commit(seq, txid, count=None, digest=None, payloads=None, **kw):
    if payloads is None:
        payloads = []
    if count is None:
        count = len(payloads)
    if digest is None:
        digest = zlib.crc32(b''.join(payloads)) & 0xffffffff
    return rec(seq, COMMIT, txid, struct.pack('<II', count, digest), **kw)

def abort(seq, txid, **kw):
    return rec(seq, ABORT, txid, b'', **kw)

def journal(*records):
    return b''.join(records).hex()

def p(page, off, data):
    """A raw PATCH payload, handy for digest computation."""
    return struct.pack('<HHH', page, off, len(data)) + data
